{
  "name": "CargoRelease System",
  "description": "A professional logistics management system for cargo release, featuring a two-step validation process for expedition and central command verification.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum CargoStatus {
  AWAITING = 'AGUARDANDO CONFERÊNCIA',
  RELEASED = 'CARGA LIBERADA',
  BLOCKED = 'CARGA BLOQUEADA'
}

export enum CargoType {
  GENERAL = 'Geral',
  FRAGILE = 'Frágil',
  HAZARDOUS = 'Perigosa',
  ELECTRONICS = 'Eletrônicos'
}

export interface CargoLoad {
  id: string;
  plate: string;
  driverName: string;
  cargoType: CargoType;
  isHighRisk: boolean;
  sealNumber: string;
  palletCount: number;
  status: CargoStatus;
  createdAt: string;
}

export interface VerificationResult {
  isMatch: boolean;
  message: string;
}

import React from 'react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: 'expedition' | 'central';
  onTabChange: (tab: 'expedition' | 'central') => void;
}

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange }) => {
  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-slate-900 text-white shadow-lg">
        <div className="container mx-auto px-4 py-4 flex flex-col md:flex-row justify-between items-center">
          <div className="flex items-center gap-2 mb-4 md:mb-0">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-xl">CR</div>
            <h1 className="text-xl font-bold tracking-tight">CargoRelease <span className="text-blue-400">System</span></h1>
          </div>
          <nav className="flex gap-1 bg-slate-800 p-1 rounded-lg">
            <button
              onClick={() => onTabChange('expedition')}
              className={`px-6 py-2 rounded-md transition-all text-sm font-medium ${
                activeTab === 'expedition' 
                  ? 'bg-blue-600 text-white shadow-sm' 
                  : 'text-slate-400 hover:text-white'
              }`}
            >
              Etapa 1: Expedição
            </button>
            <button
              onClick={() => onTabChange('central')}
              className={`px-6 py-2 rounded-md transition-all text-sm font-medium ${
                activeTab === 'central' 
                  ? 'bg-blue-600 text-white shadow-sm' 
                  : 'text-slate-400 hover:text-white'
              }`}
            >
              Etapa 2: Central
            </button>
          </nav>
        </div>
      </header>
      <main className="flex-1 container mx-auto px-4 py-8">
        {children}
      </main>
      <footer className="bg-slate-100 border-t border-slate-200 py-6 text-center text-slate-500 text-xs">
        &copy; {new Date().getFullYear()} CargoRelease System - Logística de Alta Precisão
      </footer>
    </div>
  );
};

import React, { useState } from 'react';
import { CargoLoad, CargoType, CargoStatus } from '../types';

interface ExpeditionViewProps {
  onSubmit: (load: Omit<CargoLoad, 'id' | 'status' | 'createdAt'>) => void;
}

export const ExpeditionView: React.FC<ExpeditionViewProps> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    plate: '',
    driverName: '',
    cargoType: CargoType.GENERAL,
    isHighRisk: false,
    sealNumber: '',
    palletCount: 1,
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  const validatePlate = (plate: string) => {
    // Mercosul/Brazil plate regex (AAA0A00 or AAA0000)
    const regex = /^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/;
    return regex.test(plate.toUpperCase());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, string> = {};

    if (!validatePlate(formData.plate)) {
      newErrors.plate = 'Placa inválida. Use o formato Mercosul (ex: ABC1D23) ou Antigo (ex: ABC1234)';
    }
    if (!formData.driverName.trim()) {
      newErrors.driverName = 'Nome do motorista é obrigatório';
    }
    if (!formData.sealNumber.trim()) {
      newErrors.sealNumber = 'Número do lacre é crítico';
    }
    if (formData.palletCount < 1) {
      newErrors.palletCount = 'Quantidade de paletes deve ser pelo menos 1';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    onSubmit(formData);
    setFormData({
      plate: '',
      driverName: '',
      cargoType: CargoType.GENERAL,
      isHighRisk: false,
      sealNumber: '',
      palletCount: 1,
    });
    setErrors({});
    alert('Carga enviada para conferência com sucesso!');
  };

  return (
    <div className="max-w-2xl mx-auto bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="bg-slate-50 px-8 py-6 border-b border-slate-200">
        <h2 className="text-2xl font-bold text-slate-800">Coleta de Dados</h2>
        <p className="text-slate-500 mt-1">Preencha os dados da carga para início do processo de liberação.</p>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Placa */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Placa do Caminhão</label>
            <input
              type="text"
              placeholder="ABC1D23"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all uppercase ${
                errors.plate ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.plate}
              onChange={(e) => setFormData({ ...formData, plate: e.target.value.toUpperCase() })}
            />
            {errors.plate && <span className="text-red-500 text-xs">{errors.plate}</span>}
          </div>

          {/* Nome Motorista */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Nome do Motorista</label>
            <input
              type="text"
              placeholder="Nome Completo"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.driverName ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.driverName}
              onChange={(e) => setFormData({ ...formData, driverName: e.target.value })}
            />
            {errors.driverName && <span className="text-red-500 text-xs">{errors.driverName}</span>}
          </div>

          {/* Tipo de Carga */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Tipo de Carga</label>
            <select
              className="border border-slate-300 rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white"
              value={formData.cargoType}
              onChange={(e) => setFormData({ ...formData, cargoType: e.target.value as CargoType })}
            >
              {Object.values(CargoType).map((type) => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </div>

          {/* Quantidade de Paletes */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Quantidade de Paletes</label>
            <input
              type="number"
              min="1"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.palletCount ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.palletCount}
              onChange={(e) => setFormData({ ...formData, palletCount: parseInt(e.target.value) || 0 })}
            />
            {errors.palletCount && <span className="text-red-500 text-xs">{errors.palletCount}</span>}
          </div>
        </div>

        {/* Lacre */}
        <div className="flex flex-col gap-1">
          <label className="text-sm font-semibold text-slate-700">Número do Lacre (Campo Crítico)</label>
          <input
            type="text"
            placeholder="Ex: LACRE-998877"
            className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all font-mono tracking-widest ${
              errors.sealNumber ? 'border-red-500' : 'border-slate-300'
            }`}
            value={formData.sealNumber}
            onChange={(e) => setFormData({ ...formData, sealNumber: e.target.value })}
          />
          {errors.sealNumber && <span className="text-red-500 text-xs">{errors.sealNumber}</span>}
        </div>

        {/* Alto Risco Toggle */}
        <div className="flex items-center gap-3 py-2">
          <label className="relative inline-flex items-center cursor-pointer">
            <input 
              type="checkbox" 
              className="sr-only peer" 
              checked={formData.isHighRisk}
              onChange={(e) => setFormData({ ...formData, isHighRisk: e.target.checked })}
            />
            <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-red-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-red-600"></div>
            <span className="ml-3 text-sm font-medium text-slate-700">Produtos de Alto Risco</span>
          </label>
        </div>

        <button
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-lg shadow-md transition-all active:scale-[0.98] flex items-center justify-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7"></path></svg>
          ENVIAR PARA CONFERÊNCIA
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { CargoLoad, CargoStatus } from '../types';

interface CentralViewProps {
  loads: CargoLoad[];
  onUpdateStatus: (id: string, newStatus: CargoStatus) => void;
}

export const CentralView: React.FC<CentralViewProps> = ({ loads, onUpdateStatus }) => {
  const [selectedLoadId, setSelectedLoadId] = useState<string | null>(null);
  const [sealInput, setSealInput] = useState('');
  const [verificationFeedback, setVerificationFeedback] = useState<{ type: 'error' | 'success' | null, message: string }>({ type: null, message: '' });

  const selectedLoad = loads.find(l => l.id === selectedLoadId);

  const handleVerify = () => {
    if (!selectedLoad) return;

    if (sealInput === selectedLoad.sealNumber) {
      setVerificationFeedback({ type: 'success', message: 'Lacre conferido com sucesso. Liberação autorizada.' });
    } else {
      setVerificationFeedback({ type: 'error', message: 'DIVERGÊNCIA DE LACRE: CARGA BLOQUEADA' });
    }
  };

  const handleAuthorize = () => {
    if (selectedLoad && sealInput === selectedLoad.sealNumber) {
      onUpdateStatus(selectedLoad.id, CargoStatus.RELEASED);
      setVerificationFeedback({ type: 'success', message: 'CARGA LIBERADA COM SUCESSO' });
      setSealInput('');
    }
  };

  const pendingLoads = loads.filter(l => l.status === CargoStatus.AWAITING);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-800">Painel de Conferência</h2>
          <p className="text-slate-500">Gestão de autorizações e validação de segurança.</p>
        </div>
        <div className="bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-yellow-400"></span>
            <span className="text-xs font-bold text-slate-600">Pendentes: {pendingLoads.length}</span>
          </div>
          <div className="flex items-center gap-2 border-l pl-4">
            <span className="w-3 h-3 rounded-full bg-green-500"></span>
            <span className="text-xs font-bold text-slate-600">Liberadas: {loads.filter(l => l.status === CargoStatus.RELEASED).length}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* List of Loads */}
        <div className="lg:col-span-1 bg-white rounded-xl border border-slate-200 shadow-sm h-[600px] flex flex-col">
          <div className="p-4 border-b bg-slate-50 rounded-t-xl">
            <h3 className="font-bold text-slate-700">Fila de Aguardo</h3>
          </div>
          <div className="overflow-y-auto flex-1 p-2 space-y-2">
            {pendingLoads.length === 0 ? (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhuma carga aguardando.
              </div>
            ) : (
              pendingLoads.map((load) => (
                <button
                  key={load.id}
                  onClick={() => {
                    setSelectedLoadId(load.id);
                    setVerificationFeedback({ type: null, message: '' });
                    setSealInput('');
                  }}
                  className={`w-full text-left p-4 rounded-lg border transition-all ${
                    selectedLoadId === load.id 
                      ? 'border-blue-500 bg-blue-50 ring-2 ring-blue-100' 
                      : 'border-slate-100 hover:border-slate-300'
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-mono font-bold text-lg text-slate-800">{load.plate}</span>
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                      load.isHighRisk ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-600'
                    }`}>
                      {load.isHighRisk ? 'Alto Risco' : 'Padrão'}
                    </span>
                  </div>
                  <p className="text-sm text-slate-600 truncate">{load.driverName}</p>
                  <div className="mt-2 flex items-center justify-between text-[10px] text-slate-400">
                    <span>{load.cargoType}</span>
                    <span>{new Date(load.createdAt).toLocaleTimeString()}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Verification Area */}
        <div className="lg:col-span-2 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col">
          {selectedLoad ? (
            <div className="flex flex-col h-full">
              <div className="p-6 border-b border-slate-100 bg-slate-50 rounded-t-xl flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-bold text-slate-800">Detalhes da Carga</h3>
                  <p className="text-xs text-slate-500 uppercase tracking-widest font-semibold">ID: {selectedLoad.id.split('-')[0]}</p>
                </div>
                <div className="px-4 py-1 rounded-full bg-yellow-100 text-yellow-700 text-sm font-bold border border-yellow-200">
                  {selectedLoad.status}
                </div>
              </div>

              <div className="p-8 flex-1">
                <div className="grid grid-cols-2 gap-8 mb-10">
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Motorista</p>
                    <p className="text-lg font-semibold text-slate-800">{selectedLoad.driverName}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Tipo de Mercadoria</p>
                    <p className="text-lg font-semibold text-slate-800">{selectedLoad.cargoType}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Qtd. Paletes</p>
                    <p className="text-lg font-semibold text-slate-800">{selectedLoad.palletCount}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Placa do Veículo</p>
                    <p className="text-lg font-bold text-blue-600 tracking-wider uppercase font-mono">{selectedLoad.plate}</p>
                  </div>
                </div>

                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                  <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                    <svg className="w-5 h-5 text-blue-600" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
                    Gatilho de Segurança: Verificação de Lacre
                  </h4>

                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-2">Confirmar Número do Lacre</label>
                      <div className="flex gap-2">
                        <input
                          type="text"
                          autoFocus
                          placeholder="Digite o lacre para comparar..."
                          className="flex-1 border border-slate-300 rounded-lg px-4 py-3 font-mono tracking-widest focus:ring-2 focus:ring-blue-500 outline-none"
                          value={sealInput}
                          onChange={(e) => {
                            setSealInput(e.target.value);
                            setVerificationFeedback({ type: null, message: '' });
                          }}
                        />
                        <button 
                          onClick={handleVerify}
                          className="px-6 py-3 bg-slate-800 text-white font-bold rounded-lg hover:bg-slate-700 transition-all"
                        >
                          CONFERIR
                        </button>
                      </div>
                    </div>

                    {verificationFeedback.message && (
                      <div className={`p-4 rounded-lg flex items-center gap-3 animate-pulse border ${
                        verificationFeedback.type === 'success' 
                          ? 'bg-green-50 text-green-700 border-green-200' 
                          : 'bg-red-50 text-red-700 border-red-200'
                      }`}>
                        {verificationFeedback.type === 'success' ? (
                          <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
                        ) : (
                          <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd"></path></svg>
                        )}
                        <span className="font-bold">{verificationFeedback.message}</span>
                      </div>
                    )}

                    <button
                      disabled={verificationFeedback.type !== 'success'}
                      onClick={handleAuthorize}
                      className={`w-full py-5 rounded-lg font-black text-xl shadow-xl transition-all flex items-center justify-center gap-3 ${
                        verificationFeedback.type === 'success'
                          ? 'bg-green-600 hover:bg-green-700 text-white cursor-pointer transform hover:-translate-y-1'
                          : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                      }`}
                    >
                      <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
                      AUTORIZAR SAÍDA
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center text-slate-400">
              <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mb-4">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
              </div>
              <h3 className="text-xl font-bold text-slate-500">Aguardando Seleção</h3>
              <p className="max-w-xs mx-auto">Selecione uma carga na lista lateral para iniciar o processo de conferência e liberação.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { ExpeditionView } from './views/ExpeditionView';
import { CentralView } from './views/CentralView';
import { CargoLoad, CargoStatus } from './types';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'expedition' | 'central'>('expedition');
  const [loads, setLoads] = useState<CargoLoad[]>(() => {
    const saved = localStorage.getItem('cargo_release_loads');
    return saved ? JSON.parse(saved) : [];
  });

  // Persist loads to local storage
  useEffect(() => {
    localStorage.setItem('cargo_release_loads', JSON.stringify(loads));
  }, [loads]);

  const handleAddLoad = (newLoadData: Omit<CargoLoad, 'id' | 'status' | 'createdAt'>) => {
    const newLoad: CargoLoad = {
      ...newLoadData,
      id: crypto.randomUUID(),
      status: CargoStatus.AWAITING,
      createdAt: new Date().toISOString(),
    };
    setLoads(prev => [newLoad, ...prev]);
    setActiveTab('central'); // Auto-switch to central to show the operator the new load
  };

  const handleUpdateStatus = (id: string, newStatus: CargoStatus) => {
    setLoads(prev => prev.map(load => 
      load.id === id ? { ...load, status: newStatus } : load
    ));
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab}>
      <div className="animate-in fade-in duration-500">
        {activeTab === 'expedition' && (
          <ExpeditionView onSubmit={handleAddLoad} />
        )}
        {activeTab === 'central' && (
          <CentralView loads={loads} onUpdateStatus={handleUpdateStatus} />
        )}
      </div>
    </Layout>
  );
};

export default App;

export enum CargoStatus {
  AWAITING = 'AGUARDANDO CONFERÊNCIA',
  RELEASED = 'CARGA LIBERADA',
  BLOCKED = 'CARGA BLOQUEADA'
}

export enum CargoType {
  FLV = 'FLV (Frutas, Legumes, Verduras)',
  MISTA = 'Mista',
  SECA_TRANSFERENCIA = 'Seca Transferência'
}

export interface CargoLoad {
  id: string;
  plate: string;
  driverName: string;
  cargoType: CargoType;
  origin: string;
  destination: string;
  isHighRisk: boolean;
  sealNumber: string;
  palletCount: number;
  status: CargoStatus;
  createdAt: string;
}

export interface VerificationResult {
  isMatch: boolean;
  message: string;
}

import React, { useState } from 'react';
import { CargoLoad, CargoType, CargoStatus } from '../types';

interface ExpeditionViewProps {
  onSubmit: (load: Omit<CargoLoad, 'id' | 'status' | 'createdAt'>) => void;
}

export const ExpeditionView: React.FC<ExpeditionViewProps> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    plate: '',
    driverName: '',
    cargoType: CargoType.FLV,
    origin: '',
    destination: '',
    isHighRisk: false,
    sealNumber: '',
    palletCount: 1,
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  const validatePlate = (plate: string) => {
    // Mercosul/Brazil plate regex (AAA0A00 or AAA0000)
    const regex = /^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/;
    return regex.test(plate.toUpperCase());
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, string> = {};

    if (!validatePlate(formData.plate)) {
      newErrors.plate = 'Placa inválida. Use o formato Mercosul (ex: ABC1D23)';
    }
    if (!formData.driverName.trim()) {
      newErrors.driverName = 'Nome do motorista é obrigatório';
    }
    if (!formData.origin.trim()) {
      newErrors.origin = 'Origem é obrigatória';
    }
    if (!formData.destination.trim()) {
      newErrors.destination = 'Destino é obrigatório';
    }
    if (!formData.sealNumber.trim()) {
      newErrors.sealNumber = 'Número do lacre é crítico';
    }
    if (formData.palletCount < 1) {
      newErrors.palletCount = 'Mínimo de 1 palete';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    onSubmit(formData);
    setFormData({
      plate: '',
      driverName: '',
      cargoType: CargoType.FLV,
      origin: '',
      destination: '',
      isHighRisk: false,
      sealNumber: '',
      palletCount: 1,
    });
    setErrors({});
  };

  return (
    <div className="max-w-3xl mx-auto bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="bg-slate-50 px-8 py-6 border-b border-slate-200">
        <h2 className="text-2xl font-bold text-slate-800">Coleta de Dados</h2>
        <p className="text-slate-500 mt-1">Expedição: Registro de saída de carga.</p>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Placa */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Placa do Caminhão</label>
            <input
              type="text"
              placeholder="ABC1D23"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all uppercase ${
                errors.plate ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.plate}
              onChange={(e) => setFormData({ ...formData, plate: e.target.value.toUpperCase() })}
            />
            {errors.plate && <span className="text-red-500 text-xs">{errors.plate}</span>}
          </div>

          {/* Nome Motorista */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Nome do Motorista</label>
            <input
              type="text"
              placeholder="Nome do Condutor"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.driverName ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.driverName}
              onChange={(e) => setFormData({ ...formData, driverName: e.target.value })}
            />
            {errors.driverName && <span className="text-red-500 text-xs">{errors.driverName}</span>}
          </div>

          {/* Origem */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Origem</label>
            <input
              type="text"
              placeholder="CD / Unidade de Origem"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.origin ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.origin}
              onChange={(e) => setFormData({ ...formData, origin: e.target.value })}
            />
            {errors.origin && <span className="text-red-500 text-xs">{errors.origin}</span>}
          </div>

          {/* Destino */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Destino</label>
            <input
              type="text"
              placeholder="Loja / Cliente / Filial"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.destination ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.destination}
              onChange={(e) => setFormData({ ...formData, destination: e.target.value })}
            />
            {errors.destination && <span className="text-red-500 text-xs">{errors.destination}</span>}
          </div>

          {/* Tipo de Carga */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Tipo de Carga</label>
            <select
              className="border border-slate-300 rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all bg-white"
              value={formData.cargoType}
              onChange={(e) => setFormData({ ...formData, cargoType: e.target.value as CargoType })}
            >
              {Object.values(CargoType).map((type) => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </div>

          {/* Quantidade de Paletes */}
          <div className="flex flex-col gap-1">
            <label className="text-sm font-semibold text-slate-700">Quantidade de Paletes</label>
            <input
              type="number"
              min="1"
              className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all ${
                errors.palletCount ? 'border-red-500' : 'border-slate-300'
              }`}
              value={formData.palletCount}
              onChange={(e) => setFormData({ ...formData, palletCount: parseInt(e.target.value) || 0 })}
            />
            {errors.palletCount && <span className="text-red-500 text-xs">{errors.palletCount}</span>}
          </div>
        </div>

        {/* Lacre */}
        <div className="flex flex-col gap-1">
          <label className="text-sm font-semibold text-slate-700">Número do Lacre</label>
          <input
            type="text"
            placeholder="Digite o número do lacre físico"
            className={`border rounded-lg px-4 py-2.5 focus:ring-2 focus:ring-blue-500 outline-none transition-all font-mono tracking-widest ${
              errors.sealNumber ? 'border-red-500' : 'border-slate-300'
            }`}
            value={formData.sealNumber}
            onChange={(e) => setFormData({ ...formData, sealNumber: e.target.value })}
          />
          {errors.sealNumber && <span className="text-red-500 text-xs">{errors.sealNumber}</span>}
        </div>

        <div className="flex items-center gap-3 py-2">
          <label className="relative inline-flex items-center cursor-pointer">
            <input 
              type="checkbox" 
              className="sr-only peer" 
              checked={formData.isHighRisk}
              onChange={(e) => setFormData({ ...formData, isHighRisk: e.target.checked })}
            />
            <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-red-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-red-600"></div>
            <span className="ml-3 text-sm font-medium text-slate-700">Produtos de Alto Risco</span>
          </label>
        </div>

        <button
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-lg shadow-md transition-all active:scale-[0.98] flex items-center justify-center gap-2"
        >
          ENVIAR PARA CONFERÊNCIA
        </button>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { CargoLoad, CargoStatus } from '../types';

interface CentralViewProps {
  loads: CargoLoad[];
  onUpdateStatus: (id: string, newStatus: CargoStatus) => void;
}

export const CentralView: React.FC<CentralViewProps> = ({ loads, onUpdateStatus }) => {
  const [selectedLoadId, setSelectedLoadId] = useState<string | null>(null);
  const [sealInput, setSealInput] = useState('');
  const [verificationFeedback, setVerificationFeedback] = useState<{ type: 'error' | 'success' | null, message: string }>({ type: null, message: '' });

  const selectedLoad = loads.find(l => l.id === selectedLoadId);

  const handleVerify = () => {
    if (!selectedLoad) return;

    if (sealInput === selectedLoad.sealNumber) {
      setVerificationFeedback({ type: 'success', message: 'Lacre conferido com sucesso. Liberação autorizada.' });
    } else {
      setVerificationFeedback({ type: 'error', message: 'DIVERGÊNCIA DE LACRE: CARGA BLOQUEADA' });
    }
  };

  const handleAuthorize = () => {
    if (selectedLoad && sealInput === selectedLoad.sealNumber) {
      onUpdateStatus(selectedLoad.id, CargoStatus.RELEASED);
      setVerificationFeedback({ type: 'success', message: 'CARGA LIBERADA COM SUCESSO' });
      setSealInput('');
    }
  };

  const pendingLoads = loads.filter(l => l.status === CargoStatus.AWAITING);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-800">Painel de Conferência</h2>
          <p className="text-slate-500">Controle centralizado de liberação de transporte.</p>
        </div>
        <div className="bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-yellow-400"></span>
            <span className="text-xs font-bold text-slate-600">Pendentes: {pendingLoads.length}</span>
          </div>
          <div className="flex items-center gap-2 border-l pl-4">
            <span className="w-3 h-3 rounded-full bg-green-500"></span>
            <span className="text-xs font-bold text-slate-600">Liberadas: {loads.filter(l => l.status === CargoStatus.RELEASED).length}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* List of Loads */}
        <div className="lg:col-span-1 bg-white rounded-xl border border-slate-200 shadow-sm h-[600px] flex flex-col">
          <div className="p-4 border-b bg-slate-50 rounded-t-xl">
            <h3 className="font-bold text-slate-700">Cargas em Processo</h3>
          </div>
          <div className="overflow-y-auto flex-1 p-2 space-y-2">
            {pendingLoads.length === 0 ? (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhuma carga pendente no sistema.
              </div>
            ) : (
              pendingLoads.map((load) => (
                <button
                  key={load.id}
                  onClick={() => {
                    setSelectedLoadId(load.id);
                    setVerificationFeedback({ type: null, message: '' });
                    setSealInput('');
                  }}
                  className={`w-full text-left p-4 rounded-lg border transition-all ${
                    selectedLoadId === load.id 
                      ? 'border-blue-500 bg-blue-50 ring-2 ring-blue-100' 
                      : 'border-slate-100 hover:border-slate-300'
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-mono font-bold text-lg text-slate-800">{load.plate}</span>
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                      load.isHighRisk ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-600'
                    }`}>
                      {load.isHighRisk ? 'Alto Risco' : 'Padrão'}
                    </span>
                  </div>
                  <p className="text-sm text-slate-600 truncate font-medium">{load.origin} → {load.destination}</p>
                  <div className="mt-2 flex items-center justify-between text-[10px] text-slate-400 uppercase font-bold">
                    <span>{load.cargoType.split(' ')[0]}</span>
                    <span>{new Date(load.createdAt).toLocaleTimeString()}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Verification Area */}
        <div className="lg:col-span-2 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col">
          {selectedLoad ? (
            <div className="flex flex-col h-full">
              <div className="p-6 border-b border-slate-100 bg-slate-50 rounded-t-xl flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-bold text-slate-800">Detalhes da Operação</h3>
                  <p className="text-xs text-slate-500 uppercase tracking-widest font-semibold">Placa: {selectedLoad.plate}</p>
                </div>
                <div className="px-4 py-1 rounded-full bg-yellow-100 text-yellow-700 text-sm font-bold border border-yellow-200">
                  {selectedLoad.status}
                </div>
              </div>

              <div className="p-8 flex-1">
                <div className="grid grid-cols-2 md:grid-cols-3 gap-6 mb-8">
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Motorista</p>
                    <p className="text-md font-semibold text-slate-800">{selectedLoad.driverName}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Tipo</p>
                    <p className="text-md font-semibold text-slate-800 truncate" title={selectedLoad.cargoType}>{selectedLoad.cargoType}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Paletes</p>
                    <p className="text-md font-semibold text-slate-800">{selectedLoad.palletCount}</p>
                  </div>
                  <div className="col-span-1 md:col-span-1">
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Origem</p>
                    <p className="text-md font-semibold text-blue-800">{selectedLoad.origin}</p>
                  </div>
                  <div className="col-span-1 md:col-span-2">
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Destino</p>
                    <p className="text-md font-semibold text-blue-800">{selectedLoad.destination}</p>
                  </div>
                </div>

                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                  <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                    <svg className="w-5 h-5 text-blue-600" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
                    Validação de Segurança de Lacre
                  </h4>

                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-2">Confirmar Lacre Físico</label>
                      <div className="flex gap-2">
                        <input
                          type="text"
                          placeholder="Digite o número para comparar..."
                          className="flex-1 border border-slate-300 rounded-lg px-4 py-3 font-mono tracking-widest focus:ring-2 focus:ring-blue-500 outline-none"
                          value={sealInput}
                          onChange={(e) => {
                            setSealInput(e.target.value);
                            setVerificationFeedback({ type: null, message: '' });
                          }}
                        />
                        <button 
                          onClick={handleVerify}
                          className="px-6 py-3 bg-slate-800 text-white font-bold rounded-lg hover:bg-slate-700 transition-all"
                        >
                          CONFERIR
                        </button>
                      </div>
                    </div>

                    {verificationFeedback.message && (
                      <div className={`p-4 rounded-lg flex items-center gap-3 border ${
                        verificationFeedback.type === 'success' 
                          ? 'bg-green-50 text-green-700 border-green-200' 
                          : 'bg-red-50 text-red-700 border-red-200'
                      }`}>
                        <span className="font-bold">{verificationFeedback.message}</span>
                      </div>
                    )}

                    <button
                      disabled={verificationFeedback.type !== 'success'}
                      onClick={handleAuthorize}
                      className={`w-full py-5 rounded-lg font-black text-xl shadow-xl transition-all flex items-center justify-center gap-3 ${
                        verificationFeedback.type === 'success'
                          ? 'bg-green-600 hover:bg-green-700 text-white cursor-pointer transform hover:-translate-y-1'
                          : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                      }`}
                    >
                      AUTORIZAR SAÍDA
