export const CentralView: React.FC<CentralViewProps> = ({ loads, onUpdateStatus }) => {
  const [selectedLoadId, setSelectedLoadId] = useState<string | null>(null);
  const [sealInput, setSealInput] = useState('');
  const [verificationFeedback, setVerificationFeedback] = useState<{ type: 'error' | 'success' | null, message: string }>({ type: null, message: '' });

  // Maps Integration State
  const [isCalculatingRoute, setIsCalculatingRoute] = useState(false);
  const [routeInfo, setRouteInfo] = useState<string | null>(null);
  const [routeLinks, setRouteLinks] = useState<GroundingLink[]>([]);

  const selectedLoad = loads.find(l => l.id === selectedLoadId);

  // Check if there's a static route link available for current selection
  const staticRouteLink = (selectedLoad?.origin.startsWith('CD') && selectedLoad?.destination) 
    ? CD_ROUTES_MAP[selectedLoad.destination] 
    : null;

  useEffect(() => {
    // When a load is selected, if it has a static link, we can pre-populate route links
    if (selectedLoad && staticRouteLink) {
      setRouteLinks([{ uri: staticRouteLink, title: "Abrir Rota Padrão Dia a Dia" }]);
    }
  }, [selectedLoadId, staticRouteLink]);

  const handleVerify = () => {
    if (!selectedLoad) return;

    if (sealInput === selectedLoad.sealNumber) {
      setVerificationFeedback({ type: 'success', message: 'Lacre conferido com sucesso. Liberação autorizada.' });
    } else {
      setVerificationFeedback({ type: 'error', message: 'DIVERGÊNCIA DE LACRE: CARGA BLOQUEADA' });
    }
  };

  const handleAuthorize = () => {
    if (selectedLoad && sealInput === selectedLoad.sealNumber) {
      onUpdateStatus(selectedLoad.id, CargoStatus.RELEASED);
      setVerificationFeedback({ type: 'success', message: 'CARGA LIBERADA COM SUCESSO' });
      setSealInput('');
    }
  };

  const calculateRoute = async () => {
    if (!selectedLoad) return;

    setIsCalculatingRoute(true);
    // We don't clear routeLinks if there's a static one already, we just append or supplement
    setRouteInfo(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      let latLng = undefined;
      try {
        const position = await new Promise<GeolocationPosition>((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject);
        });
        latLng = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude
        };
      } catch (e) {
        console.warn("Geolocation not available", e);
      }

      const prompt = `Calcule a rota de transporte entre as unidades do Atacadista Dia a Dia: de "${selectedLoad.origin}" para "${selectedLoad.destination}". Informe a distância aproximada, tempo estimado e valide o itinerário oficial.`;

      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: {
          tools: [{ googleMaps: {} }],
          ...(latLng && {
            toolConfig: {
              retrievalConfig: { latLng }
            }
          })
        },
      });

      setRouteInfo(response.text || "Informações de rota geradas.");

      // Extract grounding links and merge with static if available
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        const aiLinks: GroundingLink[] = chunks
          .filter((chunk: any) => chunk.maps)
          .map((chunk: any) => ({
            uri: chunk.maps.uri,
            title: chunk.maps.title || "Ver no Google Maps"
          }));

        setRouteLinks(prev => {
          const combined = [...prev];
          aiLinks.forEach(al => {
            if (!combined.find(c => c.uri === al.uri)) combined.push(al);
          });
          return combined;
        });
      }
    } catch (error) {
      console.error("Error calculating route:", error);
      setRouteInfo("Erro ao consultar itinerário via IA. Use a Rota Padrão se disponível.");
    } finally {
      setIsCalculatingRoute(false);
    }
  };

  const pendingLoads = loads.filter(l => l.status === CargoStatus.AWAITING);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-800">Painel de Conferência</h2>
          <p className="text-slate-500">Controle centralizado de liberação de transporte.</p>
        </div>
        <div className="bg-white px-4 py-2 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full bg-yellow-400"></span>
            <span className="text-xs font-bold text-slate-600">Pendentes: {pendingLoads.length}</span>
          </div>
          <div className="flex items-center gap-2 border-l pl-4">
            <span className="w-3 h-3 rounded-full bg-green-500"></span>
            <span className="text-xs font-bold text-slate-600">Liberadas: {loads.filter(l => l.status === CargoStatus.RELEASED).length}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* List of Loads */}
        <div className="lg:col-span-1 bg-white rounded-xl border border-slate-200 shadow-sm h-[700px] flex flex-col">
          <div className="p-4 border-b bg-slate-50 rounded-t-xl">
            <h3 className="font-bold text-slate-700">Cargas em Processo</h3>
          </div>
          <div className="overflow-y-auto flex-1 p-2 space-y-2">
            {pendingLoads.length === 0 ? (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhuma carga pendente no sistema.
              </div>
            ) : (
              pendingLoads.map((load) => (
                <button
                  key={load.id}
                  onClick={() => {
                    setSelectedLoadId(load.id);
                    setVerificationFeedback({ type: null, message: '' });
                    setSealInput('');
                    setRouteInfo(null);
                    setRouteLinks([]);
                  }}
                  className={`w-full text-left p-4 rounded-lg border transition-all ${
                    selectedLoadId === load.id 
                      ? 'border-blue-500 bg-blue-50 ring-2 ring-blue-100' 
                      : 'border-slate-100 hover:border-slate-300'
                  }`}
                >
                  <div className="flex justify-between items-start mb-1">
                    <span className="font-mono font-bold text-lg text-slate-800">{load.plate}</span>
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                      load.isHighRisk ? 'bg-red-100 text-red-700' : 'bg-slate-100 text-slate-600'
                    }`}>
                      {load.isHighRisk ? 'PAR' : 'Padrão'}
                    </span>
                  </div>
                  <p className="text-sm text-slate-600 truncate font-medium">{load.origin} → {load.destination}</p>
                  <div className="mt-2 flex items-center justify-between text-[10px] text-slate-400 uppercase font-bold">
                    <span>{load.cargoType.split(' ')[0]}</span>
                    <span>{new Date(load.createdAt).toLocaleTimeString()}</span>
                  </div>
                </button>
              ))
            )}
          </div>
        </div>

        {/* Verification Area */}
        <div className="lg:col-span-2 bg-white rounded-xl border border-slate-200 shadow-sm flex flex-col">
          {selectedLoad ? (
            <div className="flex flex-col h-full overflow-y-auto">
              <div className="p-6 border-b border-slate-100 bg-slate-50 sticky top-0 z-10 flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-bold text-slate-800">Detalhes da Operação</h3>
                  <p className="text-xs text-slate-500 uppercase tracking-widest font-semibold">Placa: {selectedLoad.plate}</p>
                </div>
                <div className="px-4 py-1 rounded-full bg-yellow-100 text-yellow-700 text-sm font-bold border border-yellow-200">
                  {selectedLoad.status}
                </div>
              </div>

              <div className="p-8 space-y-8">
                {/* Logistics Info Grid */}
                <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Motorista</p>
                    <p className="text-md font-semibold text-slate-800">{selectedLoad.driverName}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Tipo</p>
                    <p className="text-md font-semibold text-slate-800 truncate" title={selectedLoad.cargoType}>{selectedLoad.cargoType}</p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Paletes</p>
                    <p className="text-md font-semibold text-slate-800">{selectedLoad.palletCount}</p>
                  </div>
                  <div className="col-span-1 md:col-span-1">
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Origem</p>
                    <p className="text-md font-semibold text-blue-800">{selectedLoad.origin}</p>
                  </div>
                  <div className="col-span-1 md:col-span-2">
                    <p className="text-xs font-bold text-slate-400 uppercase mb-1">Destino</p>
                    <p className="text-md font-semibold text-blue-800">{selectedLoad.destination}</p>
                  </div>
                </div>

                {/* Google Maps Route Section */}
                <div className="bg-blue-50 border border-blue-100 rounded-xl p-6">
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="font-bold text-blue-900 flex items-center gap-2">
                      <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z" clipRule="evenodd"></path></svg>
                      {staticRouteLink ? 'Itinerário Padrão Identificado' : 'Logística de Rota (Google Maps)'}
                    </h4>
                    <button 
                      onClick={calculateRoute}
                      disabled={isCalculatingRoute}
                      className="text-xs bg-blue-600 text-white px-3 py-1.5 rounded font-bold hover:bg-blue-700 transition-all disabled:opacity-50"
                    >
                      {isCalculatingRoute ? 'CONSULTANDO...' : 'RE-CALCULAR VIA IA'}
                    </button>
                  </div>

                  {staticRouteLink && !routeInfo && !isCalculatingRoute && (
                    <div className="mb-4 p-3 bg-white/70 border border-blue-200 rounded-lg text-sm text-blue-800 font-medium">
                      Esta rota possui um itinerário oficial Dia a Dia Atacadista. Utilize o link abaixo para visualizar no mapa.
                    </div>
                  )}

                  {isCalculatingRoute && (
                    <div className="flex items-center gap-3 text-blue-600 text-sm animate-pulse mb-4">
                      <div className="w-4 h-4 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                      Analisando percurso entre unidades...
                    </div>
                  )}

                  <div className="space-y-4">
                    {routeInfo && (
                      <div className="text-sm text-blue-800 bg-white/50 p-3 rounded-lg border border-blue-200 leading-relaxed whitespace-pre-line">
                        {routeInfo}
                      </div>
                    )}

                    {routeLinks.length > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {routeLinks.map((link, idx) => (
                          <a
                            key={idx}
                            href={link.uri}
                            target="_blank"
                            rel="noopener noreferrer"
                            className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all shadow-sm border ${
                              link.uri === staticRouteLink 
                                ? 'bg-blue-600 text-white border-blue-700 hover:bg-blue-700' 
                                : 'bg-white text-blue-700 border-blue-200 hover:bg-blue-100'
                            }`}
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"></path></svg>
                            {link.title}
                          </a>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                {selectedLoad.isHighRisk && (
                  <div className="p-4 bg-red-50 border border-red-100 rounded-lg">
                    <p className="text-xs font-bold text-red-600 uppercase mb-1 flex items-center gap-1">
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd"></path></svg>
                      PAR (Alerta de Alto Risco)
                    </p>
                    <p className="text-sm font-medium text-red-900">{selectedLoad.parDescription}</p>
                  </div>
                )}

                {/* Seal Validation Section */}
                <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 mb-8">
                  <h4 className="font-bold text-slate-700 mb-4 flex items-center gap-2">
                    <svg className="w-5 h-5 text-blue-600" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path></svg>
                    Validação de Segurança de Lacre
                  </h4>

                  <div className="space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-600 mb-2">Confirmar Lacre Físico</label>
                      <div className="flex gap-2">
                        <input
                          type="text"
                          placeholder="Digite o número para comparar..."
                          className="flex-1 bg-slate-900 text-white border border-slate-700 rounded-lg px-4 py-3 font-mono tracking-widest focus:ring-2 focus:ring-blue-500 outline-none placeholder:text-slate-500"
                          value={sealInput}
                          onChange={(e) => {
                            setSealInput(e.target.value);
                            setVerificationFeedback({ type: null, message: '' });
                          }}
                        />
                        <button 
                          onClick={handleVerify}
                          className="px-6 py-3 bg-slate-800 text-white font-bold rounded-lg hover:bg-slate-700 transition-all"
                        >
                          CONFERIR
                        </button>
                      </div>
                    </div>

                    {verificationFeedback.message && (
                      <div className={`p-4 rounded-lg flex items-center gap-3 border ${
                        verificationFeedback.type === 'success' 
                          ? 'bg-green-50 text-green-700 border-green-200' 
                          : 'bg-red-50 text-red-700 border-red-200'
                      }`}>
                        <span className="font-bold">{verificationFeedback.message}</span>
                      </div>
                    )}

                    <button
                      disabled={verificationFeedback.type !== 'success'}
                      onClick={handleAuthorize}
                      className={`w-full py-5 rounded-lg font-black text-xl shadow-xl transition-all flex items-center justify-center gap-3 ${
                        verificationFeedback.type === 'success'
                          ? 'bg-green-600 hover:bg-green-700 text-white cursor-pointer transform hover:-translate-y-1'
                          : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                      }`}
                    >
                      AUTORIZAR SAÍDA
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col items-center justify-center p-12 text-center text-slate-400">
              <svg className="w-16 h-16 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"></path></svg>
              <h3 className="text-xl font-bold text-slate-500">Selecione uma carga</h3>
              <p className="max-w-xs mx-auto">As informações de logística aparecerão aqui após a seleção.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

